// ---------------------------------------------------------------------------

export const isHTML = (str: string): boolean => {

	return matches(str, /^(\s*\<!DOCTYPE.*?\>)?\s*\<html.*\<\/html\>\s*$/s)
}

// ---------------------------------------------------------------------------

export const isPug = (str: string): boolean => {

	return matches(str, /^(doctype\shtml\s)?html/s)
}

// ---------------------------------------------------------------------------

export const pug2html = (
		code: string,
		hData: hash = {}
		): string => {

	return render(code, hData)
}

// ---------------------------------------------------------------------------
// ASYNC

export const pug2htmlFile = async (
		path: string,
		hData: hash = {}
		): AutoPromise<void> => {

	const code = await Deno.readTextFile(path)
	const html = render(code, hData)
	await Deno.writeTextFile(withExt(path, '.html'), html)
	return
}

